func init() {
	seen := map[string]bool{}
	for _, m := range vulnModules {
		seen[m.ID] = true
	}
	for _, m := range genDetectModules {
		if !seen[m.ID] {
			m.Type = "detect"
			vulnModules = append(vulnModules, m)
			seen[m.ID] = true
		}
	}
	for _, m := range genExploitModules {
		if !seen[m.ID] {
			m.Type = "exploit"
			vulnModules = append(vulnModules, m)
			seen[m.ID] = true
		}
	}
}
